namespace DeliveryService.Mok.Editor {
public static class VenuePursuitUpgrade {
 public static void Apply(){var m=UnityEngine.Object.FindFirstObjectByType<VenueFinale>();if(EditorApplication.isPlaying||!m)throw new Exception("Main scene edit mode required");EditorSceneManager.SaveScene(m.gameObject.scene,"Logs/Venue-before-car-pursuit-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity",true);
 VenueGetawayBuilder.Apply();var drive=m.getaway;drive.eye=new Vector3(-.38f,1.22f,.16f);
 drive.bodyShell=drive.GetComponent<MeshFilter>();if(!drive.exteriorShell)drive.exteriorShell=drive.bodyShell.sharedMesh;
 var mesh=UnityEngine.Object.Instantiate(drive.exteriorShell);mesh.name="Venue cockpit clear roof";var vertices=mesh.vertices;
 for(int sub=0;sub<mesh.subMeshCount;sub++){var source=mesh.GetTriangles(sub);var keep=new System.Collections.Generic.List<int>();for(int t=0;t<source.Length;t+=3){Vector3 center=(vertices[source[t]]+vertices[source[t+1]]+vertices[source[t+2]])/3;if(center.y>1.22f&&center.z<1.1f)continue;keep.Add(source[t]);keep.Add(source[t+1]);keep.Add(source[t+2]);}mesh.SetTriangles(keep,sub);}mesh.RecalculateBounds();const string shellPath="Assets/Scripts/Mok/Art/VenueFinale/CockpitClearRoof.asset";var saved=AssetDatabase.LoadAssetAtPath<Mesh>(shellPath);if(saved){EditorUtility.CopySerialized(mesh,saved);UnityEngine.Object.DestroyImmediate(mesh);}else{AssetDatabase.CreateAsset(mesh,shellPath);saved=mesh;}drive.cockpitShell=drive.exteriorShell;drive.bodyShell.sharedMesh=drive.exteriorShell;

 var hands=drive.GetComponent<PrologueDrivingHands>();if(!hands){hands=drive.gameObject.AddComponent<PrologueDrivingHands>();hands.venueDrive=drive;hands.wheel=drive.GetComponentsInChildren<Transform>(true).First(t=>t.name.Contains("SteeringW"));hands.wheelRest=hands.wheel.localRotation;
 var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Synty/PolygonCity/Prefabs/Characters/Character_Male_Hoodie.prefab"),drive.transform);g.name="Getaway driver arms";hands.arms=g.transform;g.transform.localPosition=new Vector3(-.46f,-.35f,.15f);var a=g.GetComponentInChildren<Animator>();a.enabled=false;
 hands.leftUpper=a.GetBoneTransform(HumanBodyBones.LeftUpperArm);hands.leftLower=a.GetBoneTransform(HumanBodyBones.LeftLowerArm);hands.leftHand=a.GetBoneTransform(HumanBodyBones.LeftHand);hands.rightUpper=a.GetBoneTransform(HumanBodyBones.RightUpperArm);hands.rightLower=a.GetBoneTransform(HumanBodyBones.RightLowerArm);hands.rightHand=a.GetBoneTransform(HumanBodyBones.RightHand);
 foreach(var r in g.GetComponentsInChildren<SkinnedMeshRenderer>()){r.sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Scripts/Mok/Art/SyntyStory/DriverArms-Character_Male_Hoodie.asset");r.updateWhenOffscreen=true;}
 foreach(var c in g.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(c);
 Transform Grip(string name,float side){var t=new GameObject(name).transform;t.SetParent(hands.wheel,false);t.localPosition=new Vector3(side*.27f,.045f,-.015f);t.localRotation=Quaternion.Euler(side>0?180:0,0,180);return t;}
 hands.leftGrip=Grip("Getaway left grip",-1);hands.rightGrip=Grip("Getaway right grip",1);hands.leftHand.localScale=hands.rightHand.localScale=Vector3.one*.8f;
 foreach(var hand in new[]{hands.leftHand,hands.rightHand})foreach(var t in hand.GetComponentsInChildren<Transform>())if(t!=hand&&t.name.Contains("Finger")&&!t.name.EndsWith("04"))t.localRotation=Quaternion.Euler(0,0,-(t.name.EndsWith("01")?35:65));hands.Pose();}
 if(!drive.pursuit){var go=new GameObject("Gang vehicle pursuit");go.transform.SetParent(m.transform,false);var chase=go.AddComponent<VenueVehiclePursuit>();chase.drive=drive;chase.cars=new VenueVehiclePursuit.Car[2];
 for(int i=0;i<2;i++){var model=UnityEngine.Object.Instantiate(m.car.gameObject,go.transform);model.name="Gang chase car "+(i+1);var copyDrive=model.GetComponent<VenueGetawayDrive>();copyDrive.pursuit=null;UnityEngine.Object.DestroyImmediate(copyDrive);var copyHands=model.GetComponent<PrologueDrivingHands>();UnityEngine.Object.DestroyImmediate(copyHands.arms.gameObject);UnityEngine.Object.DestroyImmediate(copyHands);
 foreach(var name in new[]{m.driver.name,m.passenger.name}){var actor=model.transform.Find(name);if(actor)UnityEngine.Object.DestroyImmediate(actor.gameObject);}
 foreach(var c in model.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);
 var gang=UnityEngine.Object.Instantiate(m.preparation.enemyTemplate.gameObject,model.transform);gang.name="Gang getaway driver";foreach(var b in gang.GetComponentsInChildren<MonoBehaviour>(true))UnityEngine.Object.DestroyImmediate(b);foreach(var c in gang.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);foreach(var joint in gang.GetComponentsInChildren<Joint>(true))UnityEngine.Object.DestroyImmediate(joint);foreach(var b in gang.GetComponentsInChildren<Rigidbody>(true))UnityEngine.Object.DestroyImmediate(b);foreach(var n in gang.GetComponentsInChildren<NavMeshAgent>(true))UnityEngine.Object.DestroyImmediate(n);
 gang.transform.localPosition=new Vector3(-.48f,-.25f,-.1f);gang.transform.localRotation=Quaternion.identity;gang.transform.localScale=Vector3.one*.85f;gang.SetActive(true);var animator=gang.GetComponentInChildren<Animator>();animator.enabled=false;if(animator.isHuman){foreach(var bone in new[]{HumanBodyBones.LeftUpperLeg,HumanBodyBones.RightUpperLeg})animator.GetBoneTransform(bone).localRotation*=Quaternion.Euler(-75,0,0);foreach(var bone in new[]{HumanBodyBones.LeftLowerLeg,HumanBodyBones.RightLowerLeg})animator.GetBoneTransform(bone).localRotation*=Quaternion.Euler(85,0,0);}
 var audio=model.AddComponent<AudioSource>();audio.clip=m.engine.clip;audio.loop=true;audio.playOnAwake=false;audio.spatialBlend=1;audio.minDistance=7;audio.maxDistance=65;audio.volume=.6f;
 var lamp=new GameObject("Gang headlights");lamp.transform.SetParent(model.transform,false);lamp.transform.localPosition=new Vector3(0,.75f,1.8f);var light=lamp.AddComponent<Light>();light.type=LightType.Spot;light.spotAngle=65;light.range=28;light.intensity=2;light.shadows=LightShadows.None;
 model.transform.position=m.car.position-m.car.forward*(12+i*9);chase.cars[i]=new VenueVehiclePursuit.Car{model=model.transform,engine=audio,wheels=model.GetComponentsInChildren<Transform>(true).Where(t=>t.name.Contains("Wheel_")&&!t.name.Contains("Steering")).ToArray()};model.SetActive(false);
 }drive.pursuit=chase;EditorUtility.SetDirty(chase);}
 drive.pursuit.escapeDistance=16;drive.pursuit.maximumSpeed=9.5f;drive.pursuit.loseSeconds=2.5f;foreach(var c in drive.pursuit.cars){var crew=c.model.Find("Gang getaway driver");if(crew){foreach(var behaviour in crew.GetComponentsInChildren<MonoBehaviour>(true))behaviour.enabled=false;for(int pass=0;pass<3;pass++)foreach(var behaviour in crew.GetComponentsInChildren<MonoBehaviour>(true).Reverse())UnityEngine.Object.DestroyImmediate(behaviour);foreach(var joint in crew.GetComponentsInChildren<Joint>(true))UnityEngine.Object.DestroyImmediate(joint);foreach(var agent in crew.GetComponentsInChildren<NavMeshAgent>(true))UnityEngine.Object.DestroyImmediate(agent);foreach(var body in crew.GetComponentsInChildren<Rigidbody>(true))UnityEngine.Object.DestroyImmediate(body);foreach(var collider in crew.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(collider);crew.GetComponentInChildren<Animator>().enabled=false;}if(!c.model.GetComponent<BoxCollider>()){var collider=c.model.gameObject.AddComponent<BoxCollider>();collider.center=new Vector3(0,.85f,0);collider.size=new Vector3(1.6f,1.1f,3.3f);}}EditorUtility.SetDirty(drive.pursuit);
 EditorUtility.SetDirty(hands);EditorUtility.SetDirty(drive);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(m.gameObject.scene);EditorSceneManager.SaveScene(m.gameObject.scene);File.WriteAllText("Logs/Venue-pursuit-upgrade.txt","Saved higher cockpit, Synty steering hands, smoothed steering, two gang pursuit cars and longer route.");
 }
